const Project = ({data }) => {

const [userData , setUserData] = React.useState([]);

const projectData = userData[0]?.projects;

React.useEffect(() => {
  setUserData(data);
 
}, [data]);

  return <div className='mt-20'>
    <h3> My Projects </h3>
    <div className='mt-16'>
      {/* PROJECT LIST  */}
      <div className='w-[28rem] h-96 max-h-96  overflow-hidden border-2 border-text flex flex-col '>
      {
        projectData && projectData?.map((project,index)=>{
          return(
       <>
        <div className='basis-40'>
          {/* <img src="jiofwo" alt="" /> */}
        </div>
        <div className='flex-1 flex justify-around flex-col p-4 '>
          <h4> {project.title} </h4>
          <div>
          <p> proj unde molestiae sed nemo laboriosam laborum? Perferendis suscipit, neque dolorem ab temporibus voluptas, doloribus mollitia esse laboriosam explic</p>
          <div className='mt-2'>
            <ul className='flex flex-row flex-wrap gap-4'>
              <li>python </li>
              <li>html</li>

            </ul>
          </div>
          </div>
            <button  className='flex '>
               View Project 
            </button>
        </div>
          </>
          )
        })
      }
     </div>
    </div>
  </div>
}

export default Project;
